output_text:
[
  {
    "id": "no_cart_in_customer_aisle",
    "text": "Carts are prohibited in single-file shelf aisles between facing shelves.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "eq": [
            "freeWidthH",
            1
          ]
        },
        "betweenFacingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "customerShelfAisle": {
          "and": [
            "singleFilePassage",
            "betweenFacingShelves",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "customerShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_customer_aisle",
    "text": "A shopper may not enter a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "customerShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW",
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterCustomerShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "customerShelfAisle"
              }
            ]
          },
          "post": "customerShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterCustomerShelfAisleWithCart"
    }
  },
  {
    "id": "park_cart_at_aisle_mouth",
    "text": "After arriving with a cart at the mouth of a single-file shelf aisle, the shopper is obliged to set the cart down there before continuing.",
    "abstraction": {
      "state_properties": {
        "wideCartLane": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "customerAisleMouth": {
          "and": [
            "wideCartLane",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "arriveAtCustomerAisleMouthWithCart": {
          "pre": "MOVE",
          "post": {
            "and": [
              "customerAisleMouth",
              "hasCart"
            ]
          }
        },
        "parkCartAtCustomerAisleMouth": {
          "pre": {
            "and": [
              "customerAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arriveAtCustomerAisleMouthWithCart",
      "discharge": "parkCartAtCustomerAisleMouth"
    }
  },
  {
    "id": "only_park_at_authorized_mouth",
    "text": "If a shopper sets down a cart, it must be at an authorized wide-lane parking position near a customer-only shelf aisle.",
    "abstraction": {
      "state_properties": {
        "wideCartLane": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "authorizedCartDrop": {
          "and": [
            "wideCartLane",
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "authorizedCartDrop"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_customer_aisle_pick",
    "text": "After taking an item on foot from a single-file shelf aisle, the shopper is obliged to retrieve a cart before exiting.",
    "abstraction": {
      "state_properties": {
        "customerShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW",
            "adjShelf"
          ]
        }
      },
      "events": {
        "onFootItemInteractionInCustomerAisle": {
          "pre": {
            "and": [
              "customerShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootItemInteractionInCustomerAisle",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cart_item_pick_in_customer_aisle",
    "text": "Items in single-file shelf aisles must not be picked while the shopper is holding a cart.",
    "abstraction": {
      "state_properties": {
        "customerShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW",
            "adjShelf"
          ]
        }
      },
      "events": {
        "cartItemInteractionInCustomerAisle": {
          "pre": {
            "and": [
              "customerShelfAisle",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartItemInteractionInCustomerAisle"
    }
  },
  {
    "id": "cart_required_for_wide_shelf_pick",
    "text": "When taking an item from a shelf that is reachable from a wide shopping lane, the shopper must have the cart with them.",
    "abstraction": {
      "state_properties": {
        "wideShoppingLane": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "singleFileCustomerAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "wideLaneShelfAccess": {
          "and": [
            "wideShoppingLane",
            "adjShelf",
            {
              "not": "singleFileCustomerAisle"
            }
          ]
        }
      },
      "events": {
        "wideLaneShelfInteraction": {
          "pre": {
            "and": [
              "wideLaneShelfAccess",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideLaneShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_before_leaving_aisle_mouth",
    "text": "After leaving a single-file shelf aisle on foot into a wide lane, the shopper is obliged to pick up the cart again before proceeding to exit.",
    "abstraction": {
      "state_properties": {
        "customerShelfAisle": {
          "and": [
            {
              "eq": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW",
            "adjShelf"
          ]
        },
        "wideCartLane": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {
        "leaveCustomerAisleOnFoot": {
          "pre": {
            "and": [
              "customerShelfAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "wideCartLane"
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "leaveCustomerAisleOnFoot",
      "discharge": "pickUpCart"
    }
  }
]
